CardSpoke_MODS.register('quick-note', {
  onLoad: function(ctx) {
    var self = this;
    self._handleKeyPress = function(e) {
      if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key === 'N' && !e.altKey) {
        e.preventDefault();
        var now = new Date();
        var title = 'Quick Note ' + now.toLocaleString();
        var card = {
          title: title,
          body: '',
          tags: [],
          createdAt: now.toISOString(),
          updatedAt: now.toISOString()
        };
        try {
          if (typeof storeAPI !== 'undefined' && storeAPI.createCard) {
            storeAPI.createCard(card);
            self._showIndicator('Quick note created!');
            ctx.logger.info('Quick note created:', title);
          }
        } catch (err) {
          ctx.logger.error('Failed to create quick note:', err);
        }
      }
    };
    self._indicator = document.createElement('div');
    self._indicator.className = 'quick-note-indicator';
    document.body.appendChild(self._indicator);
    self._showIndicator = function(msg) {
      self._indicator.textContent = msg;
      self._indicator.classList.add('show');
      setTimeout(function() {
        self._indicator.classList.remove('show');
      }, 2000);
    };
    document.addEventListener('keydown', self._handleKeyPress);
    self._showIndicator('Quick Note active (Ctrl+Shift+N)');
    ctx.logger.info('Quick Note loaded');
  },
  onDisable: function(ctx) {
    if (this._handleKeyPress) {
      document.removeEventListener('keydown', this._handleKeyPress);
    }
    if (this._indicator && this._indicator.parentNode) {
      this._indicator.remove();
    }
    ctx.logger.info('Quick Note disabled');
  }
});
